import sys
from collections import deque

def solve():
    sys.setrecursionlimit(10000)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        x, y = map(int, sys.stdin.readline().split())
        adj[x].append(y)
        adj[y].append(x)

    if m < n:
        print("NO")
        return

    visited = [False] * (n+1)
    parent = [0] * (n+1)
    cycle_nodes = []
    cycle_edges = 0

    def dfs(u, p):
        nonlocal cycle_edges
        visited[u] = True
        parent[u] = p
        for v in adj[u]:
            if not visited[v]:
                if dfs(v, u):
                    return True
            elif v != p:
                cycle_nodes.append(u)
                cycle_nodes.append(v)
                cycle_edges += 1
                return True
        return False

    for u in range(1, n+1):
        if not visited[u]:
            if dfs(u, -1):
                break

    if cycle_edges != 1:
        print("NO")
        return

    cycle_nodes = list(set(cycle_nodes))
    if len(cycle_nodes) < 3:
        print("NO")
        return

    cycle = []
    u = cycle_nodes[0]
    v = cycle_nodes[1]
    cycle.append(u)
    while u != v or len(cycle) == 1:
        cycle.append(v)
        for neighbor in adj[v]:
            if neighbor != parent[v] and neighbor in cycle_nodes:
                v = neighbor
                break
    cycle.append(u)

    if len(cycle) != len(cycle_nodes):
        print("NO")
        return

    cycle_set = set(cycle)
    for u in range(1, n+1):
        if u not in cycle_set:
            visited = [False] * (n+1)
            q = deque()
            q.append(u)
            visited[u] = True
            count = 0
            while q:
                v = q.popleft()
                count += 1
                for neighbor in adj[v]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        q.append(neighbor)
            if count != len(cycle):
                print("NO")
                return

    print("FHTAGN!")

solve()
